/**
 * user-data-paths.js
 *
 * Single source of truth for every file SwitchControl persists between
 * installs.  All modules that read or write user data MUST import paths
 * from here instead of constructing them independently.
 *
 * Storage root on Windows:
 *   C:\Users\<user>\AppData\Roaming\SwitchControl\
 *
 * The NSIS uninstaller generated by electron-builder removes only the
 * application install directory (C:\Program Files\SwitchControl\).
 * It does NOT touch %APPDATA%\SwitchControl\.  User data therefore
 * survives uninstall + reinstall automatically with no extra work.
 *
 * Electron's app.getPath('userData') resolves to the same path on
 * Windows (it appends the app name to %APPDATA%).  Both approaches
 * are kept consistent by always computing the base from APPDATA here.
 */

const path = require('path');
const os   = require('os');

/**
 * %APPDATA%\SwitchControl  (e.g. C:\Users\Alice\AppData\Roaming\SwitchControl)
 * Falls back to a homedir-relative path when the env var is absent (Linux CI).
 */
const APPDATA_DIR = process.env.APPDATA
  ? path.join(process.env.APPDATA, 'SwitchControl')
  : path.join(os.homedir(), 'AppData', 'Roaming', 'SwitchControl');

module.exports = {
  /** Root directory — create this before writing any files below. */
  APPDATA_DIR,

  /** Toggle-tweak applied/reverted states (tweak-executor.js). */
  TWEAK_STATE_FILE:  path.join(APPDATA_DIR, 'tweak-state.json'),

  /** Audit log of every tweak action (tweak-executor.js). */
  TWEAK_LOG_FILE:    path.join(APPDATA_DIR, 'tweak-log.json'),

  /** User configuration — API keys, UI secrets (config-store.js). */
  CONFIG_FILE:       path.join(APPDATA_DIR, 'sc-config.json'),

  /** Stable device identifier — generated once, never regenerated. */
  DEVICE_ID_FILE:    path.join(APPDATA_DIR, 'device-id.json'),

  /** Per-device premium validation signature (generated on first premium bind). */
  DEVICE_SIGNATURE_FILE: path.join(APPDATA_DIR, 'device-signature.json'),

  /**
   * Ownership / baseline store — tracks the exact pre-change system state for
   * every premium-controlled item SwitchControl has modified.  Used by the
   * premium-expiry revert pipeline to restore the user's original configuration
   * rather than guessing a generic default.
   */
  OWNERSHIP_FILE:    path.join(APPDATA_DIR, 'ownership.json'),

  /**
   * Slider-tweak original-value backup.
   * Stores the registry value captured BEFORE the first slider write per tweak,
   * so revert always restores the user's actual previous value rather than a
   * hard-coded default.  Written by slider-tweak-executor.js.
   */
  SLIDER_STATE_FILE: path.join(APPDATA_DIR, 'slider-state.json'),

  /**
   * Slider-tweak audit log — one entry per apply / revert / blocked action.
   * Captures previousValue, newValue, success, and timestamp.
   */
  SLIDER_LOG_FILE:   path.join(APPDATA_DIR, 'slider-log.json'),

  /**
   * Crash-sentinel file for slider tweaks that require reboot.
   * Written immediately before the elevated registry write; deleted on
   * verified success.  If the app starts and finds this file, it means the
   * previous write may have caused a crash and the auto-revert flow runs.
   */
  SLIDER_CRASH_SENTINEL_FILE: path.join(APPDATA_DIR, 'slider-crash-sentinel.json'),

  /**
   * Hardware spec cache — written after the first successful background enrichment.
   * On next launch, cachedSpecs is hydrated from here instantly (zero WMI calls)
   * and enrichment only runs in the background if the cache is > 4 hours old.
   */
  SPECS_CACHE_FILE: path.join(APPDATA_DIR, 'specs-cache.json'),

  /**
   * Preset-tweak original-value backup.
   * Stores the registry values captured BEFORE the first preset-profile write
   * per tweak, so revert always restores the user's actual previous values.
   * Written by preset-tweak-executor.js.
   */
  PRESET_STATE_FILE: path.join(APPDATA_DIR, 'preset-state.json'),

  /**
   * Preset-tweak audit log — one entry per apply / revert / blocked action.
   */
  PRESET_LOG_FILE: path.join(APPDATA_DIR, 'preset-log.json'),

  /**
   * Crash-sentinel file for preset tweaks that require reboot.
   * Same purpose as SLIDER_CRASH_SENTINEL_FILE, scoped to preset profiles.
   */
  PRESET_CRASH_SENTINEL_FILE: path.join(APPDATA_DIR, 'preset-crash-sentinel.json'),

  /**
   * Debloat apply/restore history — written by the embedded backend
   * (server/lib/localDebloatHistory.ts) whenever there is no reachable
   * Postgres database (i.e. the packaged desktop app). Mirrors the shape
   * of the `debloat_applied_items` Postgres table so the client's history
   * UI works identically in both DB-backed and local-file-backed modes.
   */
  DEBLOAT_HISTORY_FILE: path.join(APPDATA_DIR, 'debloat-history.json'),

  /**
   * Original-value backup for the Maximum CPU Responsiveness tweak.
   * Stores the active scheme GUID + pre-change CPMINCORES and PERFBOOSTMODE
   * AC values so revert can restore them exactly.
   */
  CPU_RESPONSIVENESS_BACKUP_FILE: path.join(APPDATA_DIR, 'cpu-responsiveness-backup.json'),

  /**
   * Original-value backup for the GPU MSI Mode tweak.
   * Stores the selected device instance ID, registry path, and the
   * original MSISupported value (or a flag that it did not exist) so
   * revert can restore or remove the value precisely.
   */
  GPU_MSI_BACKUP_FILE: path.join(APPDATA_DIR, 'gpu-msi-backup.json'),
};
